engines.code:
/*
 * V8 ApiEngine
 * ApiEngineKey: mci-ai-content-overview
 * Version: v1.0.0
 * Function:
 * - 请补充该 V8 代码的完整功能说明。
 */

function isAdmin() {
  var user = V8.CurrentUser || {};
  return !!user.Id && (String(user.Account || '').toLowerCase() === 'admin' || Number(user.Level || 0) >= 9999);
}
if (!isAdmin()) return { Code: 0, Msg: '权限不足：只有管理员可以查看 AI 内容运营总览。' };

function count(tableName, where) {
  var result = V8.FormEngine.GetTableDataCount(tableName, { _Where: where || [] });
  if (!result || result.Code !== 1) return 0;
  if (typeof result.Data === 'number') return result.Data;
  if (result.Data && result.Data.Count !== undefined) return Number(result.Data.Count || 0);
  return Number(result.DataCount || 0);
}

return {
  Code: 1,
  Data: {
    QueuedContent: count('mci_ai_content_item', [['Status', 'In', ['Queued', 'Researching', 'Drafting']]]),
    QualityReview: count('mci_ai_content_item', [['Status', 'In', ['QualityReview', 'BlockedQuality', 'NeedsReview']]]),
    PublishPending: count('mci_ai_publish_task', [['Status', 'In', ['Pending', 'Retry', 'Claimed', 'Publishing']]]),
    PublishNeedsReview: count('mci_ai_publish_task', [['Status', '=', 'NeedsReview']]),
    Published: count('mci_ai_publish_task', [['Status', '=', 'Succeeded']]),
    GeneratedAt: DateNow('yyyy-MM-dd HH:mm:ss')
  }
};

/*
 * V8 ApiEngine
 * ApiEngineKey: mci-ai-content-dispatch
 * Version: v1.0.1
 * Function:
 * - 请补充该 V8 代码的完整功能说明。
 */

/*
 * 仅由 StopHttp 的 Microi Job 调用。Quartz 负责集群触发，SlotKey 唯一索引
 * 才是跨节点、跨重启的业务幂等事实源。
 */
var jobName = String(V8.Param.JobName || '');
if (jobName !== 'MciAiContentMorning' && jobName !== 'MciAiContentAfternoon') {
  return { Code: 0, Msg: '拒绝非预期任务调用。' };
}

var config = {};
try {
  config = V8.Param.JobParam ? JSON.parse(String(V8.Param.JobParam)) : {};
} catch (e) {
  return { Code: 0, Msg: 'JobParam 不是有效 JSON。' };
}
var slot = String(config.Slot || (jobName === 'MciAiContentMorning' ? 'am' : 'pm')).toLowerCase();
if (slot !== 'am' && slot !== 'pm') return { Code: 0, Msg: '时段只允许 am 或 pm。' };
var planKey = String(config.PlanKey || 'microi-ai-content-default');

var planResult = V8.FormEngine.GetFormData('mci_ai_content_plan', {
  _Where: [['PlanKey', '=', planKey]]
});
var plan = planResult && planResult.Code === 1 ? planResult.Data : null;
if (!plan) {
  var addPlan = V8.FormEngine.AddFormData('mci_ai_content_plan', {
    PlanKey: planKey,
    Name: '默认 AI 内容计划',
    Enabled: 1,
    Timezone: 'Asia/Shanghai',
    MorningEnabled: 1,
    AfternoonEnabled: 1,
    ArticlePrompt: '写成真实开发者解决具体问题后的技术心得，结构清晰，有代码、证据和边界，避免软文。',
    VideoPrompt: '只制作有完整信息价值的办公室工作场景视频，品牌只可作为不显眼的背景文字。',
    TargetPolicyJson: JSON.stringify({ allLiveAccounts: true }),
    QualityPolicyJson: JSON.stringify({ douyinKuaishou: { videoPreferred: true, imageCardMin: 6, imageCardMax: 9, minScore: 80 } })
  });
  if (!addPlan || addPlan.Code !== 1) {
    planResult = V8.FormEngine.GetFormData('mci_ai_content_plan', { _Where: [['PlanKey', '=', planKey]] });
    plan = planResult && planResult.Code === 1 ? planResult.Data : null;
    if (!plan) return { Code: 0, Msg: '默认内容计划创建失败：' + ((addPlan && addPlan.Msg) || '未知错误') };
  } else {
    planResult = V8.FormEngine.GetFormData('mci_ai_content_plan', { _Where: [['PlanKey', '=', planKey]] });
    plan = planResult && planResult.Code === 1 ? planResult.Data : null;
  }
}
if (Number(plan.Enabled || 0) !== 1) return { Code: 1, Data: { Skipped: true, Reason: 'PlanDisabled' }, Msg: '内容计划已停用。' };
if ((slot === 'am' && Number(plan.MorningEnabled || 0) !== 1) || (slot === 'pm' && Number(plan.AfternoonEnabled || 0) !== 1)) {
  return { Code: 1, Data: { Skipped: true, Reason: 'SlotDisabled', Slot: slot }, Msg: '当前时段已停用。' };
}

var fireText = String(V8.Param.ScheduledFireTime || V8.Param.FireTime || '');
var shanghaiDate;
try {
  var utc = fireText ? new Date(fireText) : new Date();
  shanghaiDate = DateAdd(utc, 'h', 8, 'yyyy-MM-dd');
} catch (e) {
  shanghaiDate = DateAdd(new Date(), 'h', 8, 'yyyy-MM-dd');
}
var slotKey = shanghaiDate + '-' + slot;
var existing = V8.FormEngine.GetFormData('mci_ai_content_item', { _Where: [['SlotKey', '=', slotKey]] });
if (existing && existing.Code === 1 && existing.Data) {
  return { Code: 1, Data: { Replayed: true, SlotKey: slotKey, ContentId: existing.Data.Id, Status: existing.Data.Status } };
}

var add = V8.FormEngine.AddFormData('mci_ai_content_item', {
  SlotKey: slotKey,
  PlanId: plan.Id,
  ContentType: 'Mixed',
  Status: 'Queued',
  QualityStatus: 'Pending',
  SourceEvidenceJson: '[]',
  PublicUrlsJson: '[]'
});
if (!add || add.Code !== 1) {
  existing = V8.FormEngine.GetFormData('mci_ai_content_item', { _Where: [['SlotKey', '=', slotKey]] });
  if (existing && existing.Code === 1 && existing.Data) {
    return { Code: 1, Data: { Replayed: true, SlotKey: slotKey, ContentId: existing.Data.Id, Status: existing.Data.Status } };
  }
  return add || { Code: 0, Msg: '内容时段创建失败。' };
}
V8.FormEngine.UptFormData('mci_ai_content_plan', { Id: plan.Id, LastDispatchTime: DateNow('yyyy-MM-dd HH:mm:ss') });
var created = V8.FormEngine.GetFormData('mci_ai_content_item', { _Where: [['SlotKey', '=', slotKey]] });
return { Code: 1, Data: { Replayed: false, SlotKey: slotKey, ContentId: created && created.Data ? created.Data.Id : '' } };

/*
 * V8 ApiEngine
 * ApiEngineKey: mci-ai-content-generate
 * Version: v1.0.1
 * Function:
 * - 请补充该 V8 代码的完整功能说明。
 */

function isAdmin() {
  var user = V8.CurrentUser || {};
  return !!user.Id && (String(user.Account || '').toLowerCase() === 'admin' || Number(user.Level || 0) >= 9999);
}
if (!isAdmin()) return { Code: 0, Msg: '权限不足：只有管理员可以调用在线 AI 生成稿件。' };

var contentId = String(V8.Param.ContentId || '');
if (!contentId) return { Code: 0, Msg: 'ContentId 不能为空。' };
var itemResult = V8.FormEngine.GetFormData('mci_ai_content_item', { Id: contentId });
if (!itemResult || itemResult.Code !== 1 || !itemResult.Data) return { Code: 0, Msg: '内容稿件不存在。' };
var item = itemResult.Data;
var planResult = V8.FormEngine.GetFormData('mci_ai_content_plan', { Id: item.PlanId });
if (!planResult || planResult.Code !== 1 || !planResult.Data) return { Code: 0, Msg: '内容计划不存在。' };
var plan = planResult.Data;

var sourceResult = V8.FormEngine.GetTableData('mci_ai_content_source', {
  _Where: [['Enabled', '=', 1]],
  _SelectFields: ['SourceKey', 'Name', 'SourceType', 'SourceUrl', 'LocalPath', 'TrustLevel', 'SourceSnapshot', 'SourceHash', 'LastVerifiedTime', 'Notes'],
  _OrderBy: 'LastVerifiedTime',
  _OrderByType: 'DESC',
  _PageIndex: 1,
  _PageSize: 8
});
var sources = sourceResult && sourceResult.Code === 1 ? (sourceResult.Data || []) : [];
var evidence = [];
var sourceText = '';
for (var i = 0; i < sources.length; i++) {
  var source = sources[i] || {};
  var snapshot = String(source.SourceSnapshot || '');
  if (snapshot.length > 5000) snapshot = snapshot.substring(0, 5000);
  sourceText += '\n\n[资料' + (i + 1) + '] ' + String(source.Name || source.SourceKey || '')
    + '\n类型：' + String(source.SourceType || '')
    + '\n地址：' + String(source.SourceUrl || source.LocalPath || '')
    + '\n最近核验：' + String(source.LastVerifiedTime || '')
    + '\n快照：' + snapshot;
  evidence.push({
    SourceKey: source.SourceKey,
    Name: source.Name,
    SourceType: source.SourceType,
    SourceUrl: source.SourceUrl,
    LocalPath: source.LocalPath,
    SourceHash: source.SourceHash,
    LastVerifiedTime: source.LastVerifiedTime
  });
}
if (sources.length === 0) return { Code: 0, Msg: '没有已启用的可信资料快照，拒绝让模型凭空写文章。' };

V8.FormEngine.UptFormData('mci_ai_content_item', { Id: item.Id, Status: 'Drafting', LastError: '' });
var systemPrompt = [
  '你是严谨的中文技术作者，只能依据提供的已核验资料快照形成文章。',
  '标题必须讲一个具体 AI 问题或技术取舍，标题中禁止出现“Microi吾码”。',
  '正文必须自然出现一次“Microi吾码AI”，但不能写成推广软文。',
  '正文按 5-8 分钟阅读设计，6-9 个短章节，段落通常 2-4 句，包含 2-4 个可改造代码块、失败或意外、证据边界。',
  '禁止虚构测试、性能数字、用户故事、截图、外部发布结果或未提供的产品行为。',
  '只返回严格 JSON，不要 Markdown 围栏：{"title":"","summary":"","markdown":"","html":""}。',
  String(plan.ArticlePrompt || '')
].join('\n');
var userPrompt = '时段：' + String(item.SlotKey || '')
  + '\n已有角度（可为空）：' + String(item.Angle || '')
  + '\n请从资料中选择一个窄而实用的新角度，生成可进入人工与质量审核的原创稿件。'
  + sourceText;
var model = String(V8.Param.AiModel || plan.DefaultAiModel || '');
var ai;
try {
  ai = await V8.AI.Chat({
    AiModel: model,
    SystemChatMsg: systemPrompt,
    UserChatMsg: userPrompt,
    ConversationId: 'mci-ai-content:' + String(item.SlotKey || item.Id)
  });
} catch (error) {
  var errorText = String(error && (error.Message || error.message) || error || '在线 AI 调用异常。');
  if (errorText.length > 1800) errorText = errorText.substring(0, 1800);
  V8.FormEngine.UptFormData('mci_ai_content_item', { Id: item.Id, Status: 'Failed', LastError: errorText });
  return { Code: 0, Msg: errorText };
}
if (!ai || ai.Code !== 1) {
  V8.FormEngine.UptFormData('mci_ai_content_item', { Id: item.Id, Status: 'Failed', LastError: (ai && ai.Msg) || '在线 AI 调用失败。' });
  return ai || { Code: 0, Msg: '在线 AI 调用失败。' };
}

var raw = typeof ai.Data === 'string' ? ai.Data : JSON.stringify(ai.Data || {});
raw = String(raw || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
var generated;
try { generated = JSON.parse(raw); } catch (e) { generated = null; }
if (!generated || !generated.title || !generated.markdown) {
  V8.FormEngine.UptFormData('mci_ai_content_item', {
    Id: item.Id,
    Markdown: raw,
    AiModel: model,
    Status: 'NeedsReview',
    QualityStatus: 'Pending',
    SourceEvidenceJson: JSON.stringify(evidence),
    GeneratedTime: DateNow('yyyy-MM-dd HH:mm:ss'),
    LastError: '模型未返回约定 JSON，原始正文已保留，需人工整理。'
  });
  return { Code: 1, Data: { ContentId: item.Id, Status: 'NeedsReview', Parsed: false }, Msg: '已保留模型原文，但需要人工整理 JSON。' };
}

var title = String(generated.title || '').trim();
var markdown = String(generated.markdown || '').trim();
var summary = String(generated.summary || '').trim();
var html = String(generated.html || '').trim();
V8.FormEngine.UptFormData('mci_ai_content_item', {
  Id: item.Id,
  Title: title,
  Summary: summary,
  Markdown: markdown,
  Html: html,
  AiModel: model,
  Status: 'QualityReview',
  QualityStatus: 'Pending',
  SourceEvidenceJson: JSON.stringify(evidence),
  GeneratedTime: DateNow('yyyy-MM-dd HH:mm:ss'),
  LastError: ''
});
return { Code: 1, Data: { ContentId: item.Id, Title: title, Status: 'QualityReview', Parsed: true, EvidenceCount: evidence.length } };

/*
 * V8 ApiEngine
 * ApiEngineKey: mci-ai-content-quality-gate
 * Version: v1.1.0
 * Function:
 * - 对文章与视频逐平台执行硬质量门禁；视频只允许唯一、带可听音轨且有 ffprobe/哈希证据的 VideoMaster，禁止把 VideoClip 分镜原片当作作品发布。
 */

function isAdmin() {
  var user = V8.CurrentUser || {};
  return !!user.Id && (String(user.Account || '').toLowerCase() === 'admin' || Number(user.Level || 0) >= 9999);
}
if (!isAdmin()) return { Code: 0, Msg: '权限不足：只有管理员可以执行质量门禁。' };

function parseJson(value, fallback) {
  if (!value) return fallback;
  if (typeof value === 'object') return value;
  try { return JSON.parse(String(value)); } catch (e) { return fallback; }
}
function plainText(value) {
  return String(value || '')
    .replace(/<topic\b[^>]*>[\s\S]*?<\/topic>/ig, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;|&#160;/ig, ' ')
    .replace(/&amp;/ig, '&')
    .replace(/&lt;/ig, '<')
    .replace(/&gt;/ig, '>')
    .replace(/&quot;/ig, '"')
    .replace(/&#39;|&apos;/ig, "'")
    .replace(/[\u0000-\u001f\u007f]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function containsMarkup(value) {
  return /<\/?(?:p|div|span|br|topic|a|strong|em)\b|<[^>]+>|&(?:lt|gt|nbsp);/i.test(String(value || ''));
}
function approved(asset) {
  return String(asset.ReviewStatus || '') === 'Approved'
    && String(asset.Status || '') === 'Approved'
    && Number(asset.QualityScore || 0) >= 80
    && String(asset.QualityReview || '').trim().length >= 20;
}
function normalizePlatform(value) {
  return String(value || '').trim().toLowerCase().replace(/\s+/g, '');
}
function assetMatches(asset, platform) {
  var target = normalizePlatform(asset && asset.Platform);
  var requested = normalizePlatform(platform);
  if (!target || target === 'all' || target === 'allplatforms' || target === 'allvideoplatforms' || target === '全部视频平台') return true;
  if (target === requested) return true;
  if (requested.indexOf('douyin') >= 0 && target.indexOf('抖音') >= 0) return true;
  if (requested.indexOf('kuaishou') >= 0 && target.indexOf('快手') >= 0) return true;
  return false;
}
function shortPlatform(value) {
  var text = normalizePlatform(value);
  return text.indexOf('douyin') >= 0 || text.indexOf('抖音') >= 0
    || text.indexOf('kuaishou') >= 0 || text.indexOf('快手') >= 0;
}
function masterReasons(asset) {
  var reasons = [];
  var info = parseJson(asset && asset.MediaInfoJson, {});
  var hash = String(asset && asset.ArtifactHash || '');
  if (Number(asset && asset.HasAudio || 0) !== 1) reasons.push('VideoMaster 未确认 HasAudio=1');
  if (!/^[a-f0-9]{64}$/i.test(hash)) reasons.push('VideoMaster 缺少 SHA-256 成片哈希');
  if (!info || Number(info.Width || 0) < 1 || Number(info.Height || 0) < 1) reasons.push('VideoMaster 缺少 ffprobe 分辨率证据');
  if (!info || Number(info.Duration || 0) < 8) reasons.push('VideoMaster 时长不足 8 秒，疑似仍是分镜原片');
  if (!info || Number(info.Fps || 0) < 1) reasons.push('VideoMaster 缺少实际 FPS 证据');
  if (!info || Number(info.AudioStreamCount || 0) < 1 || !String(info.AudioCodec || '')) reasons.push('VideoMaster 没有可验证音轨');
  if (!info || Number(info.IntegratedLoudnessLufs || -99) < -30) reasons.push('VideoMaster 音轨过静或缺少响度证据');
  return reasons;
}

var contentId = String(V8.Param.ContentId || '').trim();
if (!contentId) return { Code: 0, Msg: 'ContentId 不能为空。' };
var itemResult = V8.FormEngine.GetFormData('mci_ai_content_item', { Id: contentId });
if (!itemResult || itemResult.Code !== 1 || !itemResult.Data) return { Code: 0, Msg: '内容稿件不存在。' };
var item = itemResult.Data;
var assetsResult = V8.FormEngine.GetTableData('mci_ai_content_asset', {
  _Where: [['ContentId', '=', contentId]],
  _OrderBy: 'SequenceNo',
  _OrderByType: 'ASC',
  _PageIndex: 1,
  _PageSize: 200
});
var assets = assetsResult && assetsResult.Code === 1 ? (assetsResult.Data || []) : [];

var commonReasons = [];
var rawTitle = String(item.Title || '');
var title = plainText(rawTitle);
var markdown = String(item.Markdown || '');
var isVideoContent = String(item.ContentType || '').toLowerCase() === 'video';
if (!title) commonReasons.push('标题为空');
if (containsMarkup(rawTitle) || title.indexOf('<') >= 0 || title.indexOf('>') >= 0) commonReasons.push('标题包含 HTML/XML/topic 标记');
if (title.length > 80) commonReasons.push('标题超过视频与资讯平台通用安全长度 80 字');
if (title.indexOf('Microi吾码') >= 0) commonReasons.push('标题包含禁用品牌词');
if (!isVideoContent && markdown.length < 1200) commonReasons.push('正文信息量不足');
if (!isVideoContent && markdown.indexOf('Microi吾码AI') < 0) commonReasons.push('正文缺少约定的自然品牌露出');
if (isVideoContent && plainText(markdown).length < 60) commonReasons.push('视频说明不足，无法形成完整作品语义');
if (String(item.SourceEvidenceJson || '').length < 5) commonReasons.push('缺少来源证据');

var platformInput = V8.Param.Platforms || ['CSDN', 'Zhihu', 'Xiaohongshu', 'Weibo', 'Douyin', 'Kuaishou', 'Bilibili', 'Shipinhao', 'Baijiahao', 'Toutiaohao', 'Souhuhao'];
if (typeof platformInput === 'string') platformInput = platformInput.split(',');
var results = [];
var blocked = commonReasons.length > 0;
for (var p = 0; p < platformInput.length; p++) {
  var platform = String(platformInput[p] || '').trim();
  if (!platform) continue;
  var reasons = commonReasons.slice(0);
  var mode = isVideoContent ? 'Video' : 'Article';
  var masterAssets = [];
  var approvedCards = [];
  for (var i = 0; i < assets.length; i++) {
    var asset = assets[i] || {};
    if (!assetMatches(asset, platform) || !approved(asset)) continue;
    if (String(asset.AssetType || '') === 'VideoMaster') masterAssets.push(asset);
    if (String(asset.AssetType || '') === 'ImageCard') approvedCards.push(asset);
  }
  if (isVideoContent || shortPlatform(platform)) {
    if (masterAssets.length === 1) {
      mode = 'Video';
      reasons = reasons.concat(masterReasons(masterAssets[0]));
    } else if (!isVideoContent && approvedCards.length >= 6 && approvedCards.length <= 9) {
      mode = 'ImageText';
    } else if (masterAssets.length > 1) {
      reasons.push('同一平台只能有一个审核通过的 VideoMaster 成片');
    } else {
      reasons.push('缺少唯一审核通过的 VideoMaster 成片；VideoClip 分镜原片禁止直接发布');
    }
  }
  var passed = reasons.length === 0;
  if (!passed) blocked = true;
  results.push({
    Platform: platform,
    Passed: passed,
    Mode: mode,
    Status: passed ? 'Approved' : 'BlockedQuality',
    MasterAssetKey: masterAssets.length === 1 ? String(masterAssets[0].AssetKey || '') : '',
    Reasons: reasons
  });
}
var score = Math.max(0, 100 - commonReasons.length * 20 - results.filter(function (x) { return !x.Passed; }).length * 10);
V8.FormEngine.UptFormData('mci_ai_content_item', {
  Id: item.Id,
  Title: title,
  QualityScore: score,
  QualityStatus: blocked ? 'Blocked' : 'Approved',
  QualityResultJson: JSON.stringify(results),
  Status: blocked ? 'BlockedQuality' : 'Ready',
  LastError: blocked ? results.filter(function (x) { return !x.Passed; }).map(function (x) { return x.Platform + ': ' + x.Reasons.join('；'); }).join('\n') : ''
});
return { Code: 1, Data: { ContentId: item.Id, Passed: !blocked, Score: score, Title: title, Platforms: results }, Msg: blocked ? '质量门禁已阻断不合格平台素材。' : '质量门禁通过：每个平台只允许一个带可听音轨的 VideoMaster。' };

/*
 * V8 ApiEngine
 * ApiEngineKey: mci-ai-video-submit
 * Version: v1.0.0
 * Function:
 * - 请补充该 V8 代码的完整功能说明。
 */

function isAdmin() {
  var user = V8.CurrentUser || {};
  return !!user.Id && (String(user.Account || '').toLowerCase() === 'admin' || Number(user.Level || 0) >= 9999);
}
if (!isAdmin()) return { Code: 0, Msg: '权限不足：只有管理员可以创建 MiniMax 视频任务。' };
var assetId = String(V8.Param.AssetId || '');
if (!assetId) return { Code: 0, Msg: 'AssetId 不能为空。请先在“AI内容素材”新增 Video 资产。' };
var assetResult = V8.FormEngine.GetFormData('mci_ai_content_asset', { Id: assetId });
if (!assetResult || assetResult.Code !== 1 || !assetResult.Data) return { Code: 0, Msg: '视频资产不存在。' };
var asset = assetResult.Data;
if (String(asset.AssetType || '') !== 'VideoClip') return { Code: 0, Msg: '只有 VideoClip 分镜资产可以提交视频生成；VideoMaster 成片必须由审核通过的分镜与音乐合成。' };
var contentResult = V8.FormEngine.GetFormData('mci_ai_content_item', { Id: asset.ContentId });
if (!contentResult || contentResult.Code !== 1 || !contentResult.Data) return { Code: 0, Msg: '关联内容稿件不存在。' };
var content = contentResult.Data;
var requestId = 'mci-content:' + String(content.SlotKey || content.Id) + ':video:' + String(asset.AssetKey || asset.Id);
var result = await V8.AI.CreateMiniMaxVideo({
  RequestId: requestId,
  Prompt: String(asset.Prompt || ''),
  Model: String(asset.Model || 'MiniMax-Hailuo-2.3'),
  Duration: Number(asset.Duration || 6),
  Resolution: String(asset.Resolution || '768P'),
  FirstFrameImage: String(asset.FirstFrameUrl || '')
});
