      FileUrl: plainText(asset.FileUrl, 2000),
      ArtifactHash: plainText(asset.ArtifactHash, 100),
      HasAudio: Number(asset.HasAudio || 0),
      MediaInfo: parseJson(asset.MediaInfoJson, {}),
      QualityScore: Number(asset.QualityScore || 0)
