}

var prepared = [];
var createdCount = 0;
var replayedCount = 0;
var blockedCount = 0;
for (var a = 0; a < accounts.length; a++) {
  var account = accounts[a] || {};
  var platform = plainText(account.Platform || account.platform || account.AccountType || account.accountType || account.Type || account.type, 100);
  var accountId = plainText(account.AccountId || account.accountId || account.Id || account.id, 200);
  var accountName = plainText(account.AccountName || account.accountName || account.Name || account.name || accountId, 300);
  if (!platform || !accountId) return { Code: 0, Msg: '第 ' + (a + 1) + ' 个帐号缺少 Platform 或 AccountId。' };
  var gate = findQuality(platform);
  var mode = gate && gate.Mode ? String(gate.Mode) : 'Article';
  var reasons = [];
  if (!gate || gate.Passed !== true) reasons.push(gate && gate.Reasons ? String(gate.Reasons) : '该平台尚未通过质量门禁');
  if (isShortVideoPlatform(platform) && mode !== 'Video' && mode !== 'ImageText') reasons.push('抖音/快手只允许视频或高质量原生图文');
  var selectedAssets = collectAssets(platform, mode);
  if (mode === 'Video' && selectedAssets.length !== 1) reasons.push('视频发布必须且只能绑定一个带音轨的 VideoMaster 成片');
  if (mode === 'ImageText' && (selectedAssets.length < 6 || selectedAssets.length > 9)) reasons.push('高质量原生竖版卡片必须为 6-9 张');
  var status = reasons.length ? 'BlockedQuality' : 'Pending';
  var payload = {
    SchemaVersion: 2,
    ContentId: contentId,
    Title: cleanTitle,
    Summary: plainText(content.Summary, 2000),
    Description: plainText(content.Markdown || content.Summary, 4000),
    Markdown: String(content.Markdown || ''),
    Html: String(content.Html || ''),
    Platform: platform,
    AccountId: accountId,
    ContentMode: mode,
    Assets: selectedAssets,
    QualityGate: gate || { Passed: false, Reasons: reasons }
  };
  var extension = V8.ApiEngine.Run('mci-ai-publish-adapter-extension', {
    ContentId: contentId,
    Platform: platform,
    AccountId: accountId,
    ContentMode: mode,
    PublicPayload: payload
  });
  if (extension && extension.Code === 1 && extension.Data && extension.Data.PublicPayload) payload = extension.Data.PublicPayload;
  payload.Title = plainText(payload.Title, 80);
  payload.Description = plainText(payload.Description || payload.Summary, 4000);
  if (!payload.Title || containsMarkup(payload.Title)) return { Code: 0, Msg: platform + ' 的扩展标题不是安全纯文本。' };
  if (containsSecretKey(payload)) return { Code: 0, Msg: '发布参数检测到疑似凭据字段，已拒绝入库。' };
  var artifactIdentity = mode === 'Video' && selectedAssets.length === 1 ? selectedAssets[0].ArtifactHash : V8.EncryptHelper.Sha256Hex(JSON.stringify(selectedAssets));
  var idempotencyKey = V8.EncryptHelper.Sha256Hex(contentId + '|' + normalizePlatform(platform) + '|' + accountId + '|' + mode + '|' + artifactIdentity);
  var existing = V8.FormEngine.GetFormData('mci_ai_publish_task', { _Where: [['IdempotencyKey', '=', idempotencyKey]] });
  if (existing && existing.Code === 1 && existing.Data) {
    replayedCount++;
    prepared.push({ Id: existing.Data.Id, Platform: platform, AccountId: accountId, Status: existing.Data.Status, Replayed: true });
    continue;
  }
  var add = V8.FormEngine.AddFormData('mci_ai_publish_task', {
    IdempotencyKey: idempotencyKey,
    ContentId: contentId,
    Platform: platform,
    AccountId: accountId,
    AccountName: accountName,
    ContentMode: mode,
    Status: status,
    PayloadJson: JSON.stringify(payload),
    AttemptCount: 0,
    MaxAttempts: 3,
    FencingToken: 0,
    LastError: reasons.join('；')
  });
  if (!add || add.Code !== 1) {
    existing = V8.FormEngine.GetFormData('mci_ai_publish_task', { _Where: [['IdempotencyKey', '=', idempotencyKey]] });
    if (!existing || existing.Code !== 1 || !existing.Data) return add || { Code: 0, Msg: '发布任务创建失败。' };
    replayedCount++;
    prepared.push({ Id: existing.Data.Id, Platform: platform, AccountId: accountId, Status: existing.Data.Status, Replayed: true });
    continue;
  }
  var created = V8.FormEngine.GetFormData('mci_ai_publish_task', { _Where: [['IdempotencyKey', '=', idempotencyKey]] });
  createdCount++;
  if (status === 'BlockedQuality') blockedCount++;
  prepared.push({ Id: created && created.Data ? created.Data.Id : '', Platform: platform, AccountId: accountId, Status: status, Replayed: false });
}
V8.FormEngine.UptFormData('mci_ai_content_item', { Id: contentId, Title: cleanTitle, Status: blockedCount === accounts.length ? 'BlockedQuality' : 'Publishing' });
return {
  Code: 1,
  Data: { ContentId: contentId, AccountCount: accounts.length, Created: createdCount, Replayed: replayedCount, BlockedQuality: blockedCount, Tasks: prepared },
  Msg: blockedCount ? '发布队列已准备；不合格帐号已明确标记为 BlockedQuality。' : '全部帐号已按一个帐号一个成片准备发布队列。'
};

/*
 * V8 ApiEngine
 * ApiEngineKey: mci-ai-publish-claim
 * Version: v1.0.1
 * Function:
 * - 以共享租约和栅栏令牌安全认领待发布任务，返回非敏感内容与已审核资产；使用 DateNow/DateAdd 兼容 Jint 运行时。
 */

var user = V8.CurrentUser || {};
if (!user.Id) return { Code: 0, Msg: '未登录或访问密钥无效。' };

function safeWorker(value) {
  var worker = String(value || '').trim();
  return /^[A-Za-z0-9._:-]{1,80}$/.test(worker) ? worker : '';
}
function safeDateText(value) {
  var text = String(value || '').trim();
  return /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(text) ? text : '';
}
function parseJson(value, fallback) {
  if (!value) return fallback;
  try { return JSON.parse(String(value)); } catch (e) { return fallback; }
}

var workerId = safeWorker(V8.Param.WorkerId);
if (!workerId) return { Code: 0, Msg: 'WorkerId 只允许 1-80 位字母、数字、点、下划线、冒号或短横线。' };
var owner = String(user.Id) + ':' + workerId;
var leaseSeconds = Number(V8.Param.LeaseSeconds || 300);
if (leaseSeconds < 60) leaseSeconds = 60;
if (leaseSeconds > 900) leaseSeconds = 900;
var batchSize = Number(V8.Param.BatchSize || 5);
if (batchSize < 1) batchSize = 1;
if (batchSize > 20) batchSize = 20;
var nowText = DateNow('yyyy-MM-dd HH:mm:ss');
var leaseUntil = DateAdd(nowText, 's', leaseSeconds, 'yyyy-MM-dd HH:mm:ss');

var candidatesResult = V8.FormEngine.GetTableData('mci_ai_publish_task', {
  _Where: [['Status', 'In', ['Pending', 'Retry']]],
  _OrderBy: 'CreateTime',
  _OrderByType: 'ASC',
  _PageIndex: 1,
  _PageSize: Math.min(100, batchSize * 5)
});
var candidates = candidatesResult && candidatesResult.Code === 1 ? (candidatesResult.Data || []) : [];
var claimed = [];
for (var i = 0; i < candidates.length && claimed.length < batchSize; i++) {
  var candidate = candidates[i] || {};
  var retryAt = safeDateText(candidate.NextRetryTime);
  var activeLease = safeDateText(candidate.LeaseUntil);
  if (retryAt && retryAt > nowText) continue;
  if (activeLease && activeLease > nowText) continue;
  var oldFence = Number(candidate.FencingToken || 0);
  var affected = V8.Db.FromSql(
    "UPDATE mci_ai_publish_task SET Status=@p0,LeaseOwner=@p1,LeaseUntil=@p2,FencingToken=COALESCE(FencingToken,0)+1,AttemptCount=COALESCE(AttemptCount,0)+1,UpdateTime=@p3 " +
    "WHERE Id=@p4 AND Status IN ('Pending','Retry') AND COALESCE(FencingToken,0)=@p5 AND (LeaseUntil IS NULL OR LeaseUntil='' OR LeaseUntil<@p6)"
  )
    .AddInParameter('@p0', 'Claimed')
    .AddInParameter('@p1', owner)
    .AddInParameter('@p2', leaseUntil)
    .AddInParameter('@p3', nowText)
    .AddInParameter('@p4', candidate.Id)
    .AddInParameter('@p5', oldFence)
    .AddInParameter('@p6', nowText)
    .ExecuteNonQuery();
  if (Number(affected || 0) !== 1) continue;

  var taskResult = V8.FormEngine.GetFormData('mci_ai_publish_task', { Id: candidate.Id });
  if (!taskResult || taskResult.Code !== 1 || !taskResult.Data) continue;
  var task = taskResult.Data;
  var contentResult = V8.FormEngine.GetFormData('mci_ai_content_item', { Id: task.ContentId });
  var assetResult = V8.FormEngine.GetTableData('mci_ai_content_asset', {
    _Where: [['ContentId', '=', task.ContentId], ['Status', '=', 'Approved']],
    _OrderBy: 'SequenceNo',
    _OrderByType: 'ASC',
    _PageIndex: 1,
    _PageSize: 100
  });
  claimed.push({
    TaskId: task.Id,
    FencingToken: Number(task.FencingToken || oldFence + 1),
    LeaseUntil: task.LeaseUntil,
    Platform: task.Platform,
    AccountId: task.AccountId,
    AccountName: task.AccountName,
    ContentMode: task.ContentMode,
    AttemptNo: Number(task.AttemptCount || 1),
    Payload: parseJson(task.PayloadJson, {}),
    Content: contentResult && contentResult.Code === 1 ? contentResult.Data : null,
    Assets: assetResult && assetResult.Code === 1 ? (assetResult.Data || []) : []
  });
}
return { Code: 1, Data: { WorkerId: workerId, LeaseSeconds: leaseSeconds, Tasks: claimed }, Msg: claimed.length ? '已安全认领 ' + claimed.length + ' 个发布任务。' : '当前没有可认领的发布任务。' };

/*
 * V8 ApiEngine
 * ApiEngineKey: mci-ai-publish-complete
 * Version: v1.0.3
 * Function:
 * - 校验租约和栅栏令牌，幂等记录发布终态与非敏感证据，汇总部分失败原因，并仅在确认尚未提交时安排安全重试。
 */

var user = V8.CurrentUser || {};
if (!user.Id) return { Code: 0, Msg: '未登录或访问密钥无效。' };

function safeWorker(value) {
  var worker = String(value || '').trim();
  return /^[A-Za-z0-9._:-]{1,80}$/.test(worker) ? worker : '';
}
function safeText(value, maxLength) {
  var text = String(value || '');
  text = text
    .replace(/(authorization|cookie|token|api[_-]?key|client[_-]?secret|password|passwd)\s*[:=]\s*[^\s,;]+/ig, '$1=[REDACTED]');
  return text.length > maxLength ? text.substring(0, maxLength) : text;
}
function safeUrl(value) {
  var url = String(value || '').trim();
  return /^https?:\/\//i.test(url) ? url.substring(0, 2000) : '';
}

var workerId = safeWorker(V8.Param.WorkerId);
if (!workerId) return { Code: 0, Msg: 'WorkerId 格式不合法。' };
var owner = String(user.Id) + ':' + workerId;
var taskId = String(V8.Param.TaskId || '').trim();
var fence = Number(V8.Param.FencingToken || 0);
if (!taskId || fence < 1) return { Code: 0, Msg: 'TaskId 和 FencingToken 不能为空。' };
var resultStatus = String(V8.Param.ResultStatus || '').trim();
if (['Succeeded', 'Failed', 'NeedsReview', 'BlockedQuality'].indexOf(resultStatus) < 0) {
  return { Code: 0, Msg: 'ResultStatus 只允许 Succeeded、Failed、NeedsReview 或 BlockedQuality。' };
}

var attemptKey = taskId + ':' + fence;
var replay = V8.FormEngine.GetFormData('mci_ai_publish_attempt', { _Where: [['AttemptKey', '=', attemptKey]] });
if (replay && replay.Code === 1 && replay.Data) {
  return { Code: 1, Data: { Replayed: true, TaskId: taskId, Status: replay.Data.Status, PublicUrl: replay.Data.PublicUrl || '' }, Msg: '该栅栏令牌的结果已记录。' };
}
var taskResult = V8.FormEngine.GetFormData('mci_ai_publish_task', { Id: taskId });
if (!taskResult || taskResult.Code !== 1 || !taskResult.Data) return { Code: 0, Msg: '发布任务不存在。' };
var task = taskResult.Data;
if (String(task.LeaseOwner || '') !== owner || Number(task.FencingToken || 0) !== fence || ['Claimed', 'Publishing'].indexOf(String(task.Status || '')) < 0) {
  return { Code: 0, Msg: '租约或栅栏令牌已失效，拒绝旧工作节点回写。' };
}

var submissionState = String(V8.Param.SubmissionState || 'Unknown');
if (['NotSubmitted', 'Submitted', 'Unknown'].indexOf(submissionState) < 0) submissionState = 'Unknown';
var retryable = resultStatus === 'Failed'
  && V8.Param.Retryable === true
  && submissionState === 'NotSubmitted'
  && Number(task.AttemptCount || 0) < Number(task.MaxAttempts || 3);
var taskStatus = retryable ? 'Retry' : resultStatus;
var nowText = DateNow('yyyy-MM-dd HH:mm:ss');
var nextRetry = retryable
  ? DateAdd(nowText, 'm', Math.min(60, Math.max(2, Number(task.AttemptCount || 1) * 5)), 'yyyy-MM-dd HH:mm:ss')
  : null;
var publicUrl = safeUrl(V8.Param.PublicUrl);
var remoteTaskId = safeText(V8.Param.RemoteTaskId, 500);
var errorCode = safeText(V8.Param.ErrorCode, 200);
var errorMessage = safeText(V8.Param.ErrorMessage, 4000);
var responseSummary = safeText(V8.Param.ResponseSummary, 4000);

var affected = V8.Db.FromSql(
  "UPDATE mci_ai_publish_task SET Status=@p0,NextRetryTime=@p1,LeaseOwner=NULL,LeaseUntil=NULL,RemoteTaskId=@p2,PublicUrl=@p3,LastError=@p4,CompletedTime=@p5,UpdateTime=@p6 " +
  "WHERE Id=@p7 AND LeaseOwner=@p8 AND FencingToken=@p9 AND Status IN ('Claimed','Publishing')"
)
  .AddInParameter('@p0', taskStatus)
  .AddInParameter('@p1', nextRetry)
  .AddInParameter('@p2', remoteTaskId)
  .AddInParameter('@p3', publicUrl)
  .AddInParameter('@p4', errorMessage)
  .AddInParameter('@p5', taskStatus === 'Retry' ? null : nowText)
  .AddInParameter('@p6', nowText)
  .AddInParameter('@p7', taskId)
  .AddInParameter('@p8', owner)
  .AddInParameter('@p9', fence)
  .ExecuteNonQuery();
if (Number(affected || 0) !== 1) {
  replay = V8.FormEngine.GetFormData('mci_ai_publish_attempt', { _Where: [['AttemptKey', '=', attemptKey]] });
  if (replay && replay.Code === 1 && replay.Data) return { Code: 1, Data: { Replayed: true, TaskId: taskId, Status: replay.Data.Status } };
  return { Code: 0, Msg: '结果回写竞争失败，任务可能已被其它节点处理。' };
}

var addAttempt = V8.FormEngine.AddFormData('mci_ai_publish_attempt', {
  AttemptKey: attemptKey,
  PublishTaskId: taskId,
  AttemptNo: Number(task.AttemptCount || 1),
  FencingToken: fence,
  Status: resultStatus,
  StartedTime: safeText(V8.Param.StartedTime, 25) || nowText,
  FinishedTime: nowText,
  RemoteTaskId: remoteTaskId,
  PublicUrl: publicUrl,
  ArtifactHash: safeText(V8.Param.ArtifactHash, 100),
  PublisherNode: workerId,
  ResponseSummary: responseSummary,
  ErrorCode: errorCode,
  ErrorMessage: errorMessage
});
if (!addAttempt || addAttempt.Code !== 1) return addAttempt || { Code: 0, Msg: '发布尝试记录写入失败。' };

var taskListResult = V8.FormEngine.GetTableData('mci_ai_publish_task', {
  _Where: [['ContentId', '=', task.ContentId]],
  _PageIndex: 1,
  _PageSize: 500
});
var taskList = taskListResult && taskListResult.Code === 1 ? (taskListResult.Data || []) : [];
var succeeded = 0;
var unresolved = 0;
var failed = 0;
var urls = [];
var failureSummaries = [];
for (var i = 0; i < taskList.length; i++) {
  var row = taskList[i] || {};
  var rowStatus = row.Id === taskId ? taskStatus : String(row.Status || '');
  if (rowStatus === 'Succeeded') {
    succeeded++;
    var url = row.Id === taskId ? publicUrl : safeUrl(row.PublicUrl);
    if (url) urls.push({ Platform: row.Platform, AccountName: row.AccountName, Url: url });
  } else if (['Failed', 'BlockedQuality', 'NeedsReview'].indexOf(rowStatus) >= 0) {
    failed++;
    var rowError = row.Id === taskId ? errorMessage : safeText(row.LastError, 1000);
    if (rowError && failureSummaries.length < 20) {
      failureSummaries.push(safeText(row.Platform, 100) + '：' + rowError);
    }
  } else {
    unresolved++;
  }
}
var contentStatus = unresolved > 0 ? 'Publishing' : (succeeded > 0 ? (failed > 0 ? 'PartiallyPublished' : 'Published') : (failed > 0 ? 'NeedsReview' : 'Ready'));
var contentError = failureSummaries.join('；');
V8.FormEngine.UptFormData('mci_ai_content_item', {
  Id: task.ContentId,
  Status: contentStatus,
  PublicUrlsJson: JSON.stringify(urls),
  PublishedTime: unresolved === 0 && succeeded > 0 ? nowText : null,
  LastError: ['PartiallyPublished', 'NeedsReview'].indexOf(contentStatus) >= 0
    ? safeText(contentError || errorMessage, 2000)
    : ''
});

return {
  Code: 1,
  Data: { Replayed: false, TaskId: taskId, AttemptKey: attemptKey, TaskStatus: taskStatus, ContentStatus: contentStatus, RetryAt: nextRetry, PublicUrl: publicUrl },
  Msg: retryable ? '确认请求尚未提交，已进入安全重试。' : (resultStatus === 'Succeeded' ? '发布结果和公开页面地址已记录。' : '发布结果已记录，未进行不安全的自动重试。')
};

/*
 * V8 ApiEngine
 * ApiEngineKey: mci-ai-scheduler-reconcile
 * Version: v1.0.3
 * Function:
 * - 管理员幂等校准 AI 内容发布的 08:30、16:30 与 MiniMax 音乐持久 Worker，并在触发器已存在时修复 diy_schedule_job 元数据状态。
