  existing = V8.FormEngine.GetFormData('diy_schedule_job', { _Where: [['JobName', '=', item.JobName]] });
  if (!existing || existing.Code !== 1 || !existing.Data) return { Code: 0, Msg: '调度元数据写入后回读失败：' + item.JobName };
